script:
(function () {
  'use strict';
  // Annuity payout (drawdown) for a lump sum P earning a steady return.
  //   Periodic rate i: effective annual r -> (1 + r)^(1/k) - 1; nominal r -> r / k (k payouts a year).
  //   Level payout for n periods, leaving L at the end (payouts at period end):
  //     PMT = (P - L * v^n) * i / (1 - v^n), v = 1 / (1 + i); i = 0 -> (P - L) / n.
  //   Payouts at the start of each period: PMT / (1 + i).
  //   "How long it lasts" is found by running the balance forward period by period; the last payout
  //   is whatever is left above L.
  // Verified (Node): $500,000, 6% effective, 10 years, monthly, end -> $5,511.20 (matches the
  // calculator.net default result); same at 6% nominal -> $5,551.03 (standard PMT, Excel
  // PMT(0.5%, 120, -500000)); annual 5%, $100,000, 10 years -> $12,950.46; beginning-of-period
  // -> $12,333.77; 0% rate $120,000 over 10 years monthly -> $1,000.00; duration mode with
  // $5,551.03 at 6% nominal monthly on $500,000 -> 120 payouts
  // (exact payout also 120, not 121); balance simulation ends at $0.00; $100,000 at 5% yearly, start-of-
  // period payouts, $20,000 left at the end -> balance after year 10 is exactly $20,000.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var NAMES = { '1': 'Annual', '2': 'Semiannual', '4': 'Quarterly', '12': 'Monthly', '24': 'Semimonthly', '26': 'Biweekly', '52': 'Weekly' };
  var MAX_YEARS = 100;

  // --- calc start
  function periodicRate(annual, k, basis) {
    return basis === 'nominal' ? annual / k : Math.pow(1 + annual, 1 / k) - 1;
  }

  function levelPayout(P, i, n, L, due) {
    var pmt;
    if (i === 0) pmt = (P - L) / n;
    else {
      var v = Math.pow(1 + i, -n);
      pmt = (P - L * v) * i / (1 - v);
    }
    return due ? pmt / (1 + i) : pmt;
  }

  // Runs the balance forward. Stops after maxPeriods or when the balance can no longer
  // cover a full payout (that period pays what is left above L).
  function runDown(P, i, X, L, due, maxPeriods) {
    var bal = P, periods = [], exhausted = false;
    for (var t = 1; t <= maxPeriods; t++) {
      var start = bal, pay, ret;
      if (due) {
        pay = Math.min(X, Math.max(bal - L / (1 + i), 0));
        bal -= pay;
        ret = bal * i;
        bal += ret;
      } else {
        ret = bal * i;
        bal += ret;
        pay = Math.min(X, Math.max(bal - L, 0));
        bal -= pay;
      }
      periods.push({ start: start, ret: ret, pay: pay, end: bal });
      if (pay < X - 0.005 || bal - L < 0.005) { exhausted = true; break; }
    }
    return { periods: periods, exhausted: exhausted };
  }
  // --- calc end

  function el(id) { return document.getElementById(id); }
  function pct(x, dp) {
    return (x * 100).toLocaleString('en-US', { minimumFractionDigits: dp, maximumFractionDigits: dp }) + '%';
  }
  function show(id, on) { el(id).hidden = !on; }

  function clear() {
    ['apMain', 'apTotal', 'apEarned', 'apCount', 'apPeriodRate', 'apYearly', 'apLast', 'apEndBalance'].forEach(function (id) {
      el(id).textContent = '–';
    });
    el('apSchedule').innerHTML = '';
    el('apNote').hidden = true;
  }

  function yearRows(periods, k) {
    var rows = [];
    for (var s = 0; s < periods.length; s += k) {
      var chunk = periods.slice(s, s + k), ret = 0, pay = 0;
      chunk.forEach(function (p) { ret += p.ret; pay += p.pay; });
      rows.push({ year: s / k + 1, start: chunk[0].start, ret: ret, pay: pay, end: chunk[chunk.length - 1].end });
    }
    return rows;
  }

  function update() {
    var mode = el('apSolve').value;
    show('apYearsWrap', mode === 'amount');
    show('apPayoutWrap', mode === 'duration');
    var P = parseFloat(el('apPrincipal').value), rate = parseFloat(el('apRate').value);
    var k = parseInt(el('apFreq').value, 10) || 12;
    var years = parseFloat(el('apYears').value), X = parseFloat(el('apPayout').value);
    var leaveText = el('apLeave').value.trim();
    var L = leaveText === '' ? 0 : parseFloat(leaveText);
    var due = el('apTiming').value === 'begin';
    var basis = el('apBasis').value;
    var unit = NAMES[String(k)] || 'Periodic';
    el('apMainLabel').textContent = mode === 'amount' ? unit + ' payout' : 'Money lasts';

    var msg = '';
    if (isNaN(P) || P <= 0 || P > 1e12) msg = 'Enter a starting balance above $0 and up to $1 trillion.';
    else if (isNaN(rate) || rate < 0 || rate > 50) msg = 'Enter a return rate from 0% to 50%.';
    else if (isNaN(L) || L < 0 || L > 1e12) msg = 'Enter a balance to leave of $0 or more.';
    else if (mode === 'amount' && (isNaN(years) || years < 1 || years > 60)) msg = 'Enter 1 to 60 years of payouts.';
    else if (mode === 'duration' && (isNaN(X) || X <= 0 || X > 1e12)) msg = 'Enter a payout above $0.';
    var i = periodicRate(rate / 100, k, basis), n = Math.round(years * k), payout = X;
    if (!msg && mode === 'amount') {
      payout = levelPayout(P, i, n, L, due);
      if (!(payout > 0) || !isFinite(payout)) msg = 'The balance to leave is more than the starting balance can grow to, so there is nothing to pay out.';
    }
    if (!msg && mode === 'duration' && L >= P) msg = 'The balance to leave must be less than the starting balance.';
    var error = el('apError');
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clear(); return; }

    var maxPeriods = mode === 'amount' ? n : MAX_YEARS * k;
    var run = runDown(P, i, payout, L, due, maxPeriods);
    var total = 0, earned = 0;
    run.periods.forEach(function (p) { total += p.pay; earned += p.ret; });
    var count = run.periods.length, last = run.periods[count - 1];
    var note = el('apNote');
    note.hidden = true;

    if (mode === 'amount') {
      el('apMain').textContent = money.format(payout);
    } else if (!run.exhausted) {
      el('apMain').textContent = 'Over ' + MAX_YEARS + ' years';
      note.textContent = 'This payout is no more than the return the balance earns, so the money does not run out. The table shows the first ' + MAX_YEARS + ' years.';
      note.hidden = false;
    } else {
      var yrs = count / k;
      if (k === 12) {
        var y = Math.floor(count / 12), m = count % 12;
        el('apMain').textContent = y + (y === 1 ? ' year' : ' years') + (m ? ', ' + m + (m === 1 ? ' month' : ' months') : '');
      } else {
        el('apMain').textContent = yrs.toLocaleString('en-US', { maximumFractionDigits: 1 }) + (yrs === 1 ? ' year' : ' years');
      }
    }
    el('apTotal').textContent = money.format(total);
    el('apEarned').textContent = money.format(earned);
    el('apCount').textContent = count.toLocaleString('en-US');
    el('apPeriodRate').textContent = pct(i, 4);
    el('apYearly').textContent = money.format(payout * k);
    el('apLast').textContent = money.format(last.pay);
    el('apEndBalance').textContent = money.format(Math.abs(last.end) < 0.005 ? 0 : last.end);

    el('apSchedule').innerHTML = yearRows(run.periods, k).map(function (r) {
      return '<tr><td>' + r.year + '</td><td>' + money.format(r.start) + '</td><td>' + money.format(r.ret) + '</td><td>' +
             money.format(r.pay) + '</td><td>' + money.format(Math.abs(r.end) < 0.005 ? 0 : r.end) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('apForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
